urlset:
{%- for entry in entries %}
  {%- set_global lastmod = entry.updated %}
  {%- set path = entry.permalink | replace(from=root, to="") %}
  {%- for d in dates %}{% if d.path == path %}{% set_global lastmod = d.lastmod %}{% endif %}{% endfor %}
  {{ entry.permalink | safe }}{% if lastmod %}{{ lastmod }}{% endif %}
{%- endfor %}
